INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (1, 'Independence Day', '1996-10-14', 306169255.0, 145, 7.0, 12, 'The aliens are coming and their goal is to invade and destroy Earth. Fighting superior technology, mankind''s best weapon is the will to survive.', 28779786.2474101, 2);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (2, 'Scott Pilgrim vs. the World', '2010-11-22', 31494270.0, 112, 7.5, 12, 'In a magically realistic version of Toronto, a young man must defeat his new girlfriend''s seven evil exes one by one in order to win her heart.', 2991831.9274101, 2);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (3, 'The Fast and the Furious', '2001-12-13', 144533925.0, 106, 6.8, 12, 'Los Angeles police officer Brian O''Conner must decide where his loyalty really lies when he becomes enamored with the street racing world he has been sent undercover to destroy.', 13528251.6574101, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (4, 'Barb Wire', '1996-08-25', 3794000.0, 98, 3.5, 16, 'During the Second American Civil War in 2017, Barb Wire owns a nightclub called the Hammerhead. Things become complicated when her ex-lover Axel Hood, who is married to the fugitive Corrina Devonshire, re-enters her life.', 329954.2774101, 2);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (5, 'No Time to Die', '2021-04-04', 160869031.0, 163, 7.3, 12, 'James Bond has left active service. His peace is short-lived when Felix Leiter, an old friend from the CIA, turns up asking for help, leading Bond onto the trail of a mysterious villain armed with dangerous new technology.', 15218086.6100101, 1);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (6, 'Son of Rambow', '2007-04-08', 1784769.0, 96, 7.0, 12, 'During a long English summer in the early 1980s, two schoolboys from differing backgrounds set out to make a film inspired by First Blood (1982).', 167644.5634101, 1);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (7, 'Rosewood', '1997-05-02', 13104494.0, 140, 7.2, 16, 'A dramatization of a 1923 horrific racist lynch mob attack on an African-American community.', 1236940.5110101, 1);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (8, 'Robot Jox', '1989-08-03', 1272977.0, 85, 5.4, 0, 'In the distant future, mankind has forsaken global wars for battles of single combat. The world has been divided into two opposing super powers, with each side represented by trained champions.', 115462.5890101, 1);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (9, 'Caged Heat', '1974-01-08', 100300.0, 80, 5.3, 16, 'In a women''s prison, a group of inmates band together to combat the repressive and abusive policies of the warden and the corrupt prison doctor.', 8963.4574101, 2);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (10, 'Pawn Shop Chronicles', '2013-04-23', 4915.0, 112, 5.9, 16, 'An anthology of stories involving meth addicted white supremacists, a man looking for his kidnapped wife and an Elvis impersonator.', 327.4744101, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (11, 'Wonder Woman 1984', '2020-08-25', 46370364.0, 151, 5.4, 12, 'Diana must contend with a work colleague, and with a businessman whose desire for extreme wealth sends the world down a path of destruction, after an ancient artifact that grants wishes goes missing.', 4210424.907501944, 6);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (12, 'Deadpool 2', '2018-04-15', 324591735.0, 119, 7.7, 16, 'Foul-mouthed mutant mercenary Wade Wilson (a.k.a. Deadpool) assembles a team of fellow mutant rogues to protect a young boy with supernatural abilities from the brutal, time-traveling cyborg Cable.', 30966047.375301942, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (13, 'Kingsman: The Secret Service', '2014-10-16', 128261724.0, 129, 7.7, 16, 'A spy organisation recruits a promising street kid into the agency''s training program, while a global threat emerges from a twisted tech genius.', 12236164.325901944, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (14, 'Pirates of the Caribbean: The Curse of the Black Pearl', '2003-11-13', 305413918.0, 143, 8.1, 12, 'Blacksmith Will Turner teams up with eccentric pirate "Captain" Jack Sparrow to save his love, the governor''s daughter, from Jack''s former pirate allies, who are now undead.', 29380814.767901946, 6);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (15, 'Ant-Man and the Wasp', '2018-01-27', 216648740.0, 118, 7.0, 12, 'As Scott Lang balances being both a superhero and a father, Hope van Dyne and Dr. Hank Pym present an urgent new mission that finds the Ant-Man fighting alongside The Wasp to uncover secrets from their past.', 20364977.416301943, 2);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (16, 'The Rock', '1996-08-10', 134069511.0, 136, 7.4, 16, 'A mild-mannered chemist and an ex-con must lead the counterstrike when a rogue group of military men, led by a renegade general, threaten a nerve gas attack from Alcatraz against San Francisco.', 12709785.499101944, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (17, 'Ratatouille', '2007-04-11', 206445654.0, 111, 8.1, 16, 'A rat who can cook makes an unusual alliance with a young kitchen worker at a famous Paris restaurant.', 19860067.771101944, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (18, 'Black Widow', '2021-09-27', 183651655.0, 134, 6.7, 12, 'Natasha Romanoff confronts the darker parts of her ledger when a dangerous conspiracy with ties to her past arises.', 17153060.433301944, 6);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (19, 'Shang-Chi and the Legend of the Ten Rings', '2021-04-04', 224543292.0, 132, 7.4, 12, 'Shang-Chi, the master of weaponry-based Kung Fu, is forced to confront his past after being drawn into the Ten Rings organization.', 21286699.937901944, 6);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (20, 'Frozen', '2013-01-02', 400738009.0, 102, 7.4, 0, 'When the newly crowned Queen Elsa accidentally uses her power to turn things into ice to curse her home in infinite winter, her sister Anna teams up with a mountain man, his playful reindeer, and a snowman to change the weather condition.', 37989959.10950194, 3);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (21, 'The Addams Family', '1991-04-24', 113502000.0, 99, 6.9, 12, 'Con artists plan to fleece an eccentric family using an accomplice who claims to be their long-lost uncle.', 10646281.60505468, 5);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (22, 'The Hobbit: An Unexpected Journey', '2012-04-07', 303003568.0, 169, 7.8, 12, 'A reluctant Hobbit, Bilbo Baggins, sets out to the Lonely Mountain with a spirited group of dwarves to reclaim their mountain home, and the gold within it from the dragon Smaug.', 28966935.105854683, 5);
