INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (81, 'A Quiet Place', '2018-07-19', 188024361.0, 90, 7.5, 12, 'A family struggles for survival in a world where most humans have been killed by blind but noise-sensitive creatures. They are forced to communicate in sign language to keep the creatures at bay.', 16921972.53186929, 10);
INSERT INTO Titulo (id_titulo, nome_titulo, data_lancamento_pais_origem, bilheteria, duracao, avaliacao_critica, classificacao_etaria, sinopse, orcamento, id_estudio) VALUES (82, 'Alien: Covenant', '2017-07-09', 74262031.0, 122, 6.4, 16, 'The crew of a colony ship, bound for a remote planet, discover an uncharted paradise with a threat beyond their imagination, and must attempt a harrowing escape.', 6356609.895469287, 11);
